class Solution {
public:
    long long makeSimilar(std::vector<int>& nums, std::vector<int>& target) {
        std::vector<int> n_even, n_odd, t_even, t_odd;
        for (int x : nums) (x % 2 == 0 ? n_even : n_odd).push_back(x);
        for (int x : target) (x % 2 == 0 ? t_even : t_odd).push_back(x);
        std::sort(n_even.begin(), n_even.end());
        std::sort(n_odd.begin(), n_odd.end());
        std::sort(t_even.begin(), t_even.end());
        std::sort(t_odd.begin(), t_odd.end());
        long long diff = 0;
        for (size_t i = 0; i < n_even.size(); ++i) diff += std::abs(n_even[i] - t_even[i]);
        for (size_t i = 0; i < n_odd.size(); ++i) diff += std::abs(n_odd[i] - t_odd[i]);
        return diff / 4;
    }
};

class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        java.util.List<Integer> nEven = new java.util.ArrayList<>();
        java.util.List<Integer> nOdd = new java.util.ArrayList<>();
        java.util.List<Integer> tEven = new java.util.ArrayList<>();
        java.util.List<Integer> tOdd = new java.util.ArrayList<>();
        for (int x : nums) { if (x % 2 == 0) nEven.add(x); else nOdd.add(x); }
        for (int x : target) { if (x % 2 == 0) tEven.add(x); else tOdd.add(x); }
        java.util.Collections.sort(nEven);
        java.util.Collections.sort(nOdd);
        java.util.Collections.sort(tEven);
        java.util.Collections.sort(tOdd);
        long diff = 0;
        for (int i = 0; i < nEven.size(); i++) diff += Math.abs((long)nEven.get(i) - tEven.get(i));
        for (int i = 0; i < nOdd.size(); i++) diff += Math.abs((long)nOdd.get(i) - tOdd.get(i));
        return diff / 4;
    }
}

var makeSimilar = function(nums, target) {
    const nEven = nums.filter(x => x % 2 === 0).sort((a, b) => a - b);
    const nOdd = nums.filter(x => x % 2 !== 0).sort((a, b) => a - b);
    const tEven = target.filter(x => x % 2 === 0).sort((a, b) => a - b);
    const tOdd = target.filter(x => x % 2 !== 0).sort((a, b) => a - b);
    let diff = 0;
    for (let i = 0; i < nEven.length; i++) diff += Math.abs(nEven[i] - tEven[i]);
    for (let i = 0; i < nOdd.length; i++) diff += Math.abs(nOdd[i] - tOdd[i]);
    return Math.floor(diff / 4);
};
